import{_ as t,o as a,c as o,ao as i}from"./chunks/framework.CDNWU7eT.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"GeophysicalModelGenerator.jl","text":"From geophysical data to 3D models","tagline":"Import, combine, and visualize geophysical data sets, and create input models for geodynamic simulations.","actions":[{"theme":"brand","text":"Getting Started","link":"/man/Tutorial_Basic"},{"theme":"alt","text":"Tutorials","link":"/man/tutorials"},{"theme":"alt","text":"API Reference","link":"/man/listfunctions"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/JuliaGeodynamics/GeophysicalModelGenerator.jl"}],"image":{"src":"/logo.svg","alt":"GeophysicalModelGenerator.jl"}},"features":[{"title":"Consistent data structures","details":"GeoData, CartData and UTMData hold data together with its lon/lat/depth or Cartesian coordinates.","link":"/man/datastructures"},{"title":"Data import","details":"Import seismic tomography, topography, earthquake catalogs, GPS data, and screenshots of published figures.","link":"/man/dataimport"},{"title":"Paraview output","details":"Write points, 2D profiles, and 3D volumes, for scalar and vector data, to VTK files.","link":"/man/paraview_output"},{"title":"Numerical model setups","details":"Create 2D and 3D geodynamic input models for LaMEM, pTatin, and other codes.","link":"/man/geodynamic_setups"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),s={name:"index.md"};function r(l,e,n,d,p,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h2 id="What-is-GeophysicalModelGenerator.jl?" tabindex="-1">What is GeophysicalModelGenerator.jl? <a class="header-anchor" href="#What-is-GeophysicalModelGenerator.jl?" aria-label="Permalink to &quot;What is GeophysicalModelGenerator.jl? {#What-is-GeophysicalModelGenerator.jl?}&quot;">​</a></h2><p>Documentation for <a href="https://github.com/JuliaGeodynamics/GeophysicalModelGenerator.jl" target="_blank" rel="noreferrer">GeophysicalModelGenerator</a>.</p><p>The main purpose of this package is to simplify the process of going from 1D/2D/3D geophysical data to a 3D consistent model of the region. By simplifying the process of plotting the data, it becomes easier to compare different data sets, and generate a 3D models that can be used for other computations such as geodynamic simulations, or forward modelling of gravity anomalies.</p><p>For this, GeophysicalModelGenerator provides the following functionality:</p><ul><li><p>A consistent GeoData structure, that holds the data along with lon/lat/depth information.</p></li><li><p>Routines to generate VTK files from the GeoData structure in order to visualize results in Paraview.</p></li><li><p>The ability to deal with points, 2D profiles and 3D volumes, for both scalar and vector values.</p></li><li><p>Rapidly import screenshots of published papers and compare them with other data sets in 3D using paraview.</p></li><li><p>Create movies for representation of earthquake or wave propagation.</p></li><li><p>Create geodynamic input models (for LaMEM)</p></li></ul><p>The best way to get started is to look at the tutorials.</p>',6)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
